-- Day1朝 検索カードリサーチ
INSERT INTO scenario_steps (id, scenario_id, step_order, delay_minutes, message_type, message_content, offset_days, offset_minutes, delivery_time)
VALUES ('6570ac07-c75e-41f8-aa01-9b3ec8bb718c', '373c47a6-0197-419d-89ed-9e01dcc298c4', 1, 0, 'flex', '{"type":"flex","altText":"【導入した瞬間から、変わります】無料のリサーチ機能がもう動いています","contents":{"type":"bubble","size":"mega","header":{"type":"box","layout":"vertical","backgroundColor":"#2FA25B","paddingAll":"12px","contents":[{"type":"text","text":"無料ステップ 1/3｜導入した瞬間から","color":"#FFFFFF","weight":"bold","size":"sm","wrap":true}]},"body":{"type":"box","layout":"vertical","spacing":"md","paddingAll":"16px","contents":[{"type":"text","text":"導入した瞬間から、変わります","size":"lg","color":"#333333","wrap":true,"weight":"bold"},{"type":"text","text":"拡張機能は導入できましたか？\n\n導入すると、無料のリサーチ機能があなたのメルカリですぐに動き始めます。\n\n試しに、メルカリで何か検索してみてください🔍","size":"sm","color":"#555555","wrap":true},{"type":"text","text":"▼ 導入前の検索結果","size":"xs","color":"#888888","wrap":true,"margin":"md"},{"type":"image","url":"https://furimauto.com/howto/images/freeFeature_mercari_search_before.png","size":"full","aspectRatio":"2260:1760","aspectMode":"cover"},{"type":"text","text":"▼ 導入後：評価・本人確認・出品日時・SOLDの\"売れた日時\"が自動で追加","size":"xs","color":"#D94A3D","wrap":true,"weight":"bold","margin":"md"},{"type":"image","url":"https://furimauto.com/howto/images/freeFeature_mercari_search_after.png","size":"full","aspectRatio":"2260:1658","aspectMode":"cover"},{"type":"text","text":"設定も操作もいりません。\n「いつ・何が・どれだけ売れているか」が見えるだけで、仕入れの精度は大きく変わります。\n\nまだ導入がお済みでない方は、下のボタンから1分でどうぞ👇","size":"sm","color":"#555555","wrap":true,"margin":"md"}]},"footer":{"type":"box","layout":"vertical","spacing":"sm","contents":[{"type":"button","style":"secondary","height":"sm","action":{"type":"uri","label":"拡張機能を導入（1分）","uri":"https://furimauto.com/install"}}]}}}', 1, NULL, '09:00');

-- Day1昼 特典への道1/6
INSERT INTO scenario_steps (id, scenario_id, step_order, delay_minutes, message_type, message_content, offset_days, offset_minutes, delivery_time)
VALUES ('4891d8a3-5726-41fa-8849-3fa69ffec0e6', '373c47a6-0197-419d-89ed-9e01dcc298c4', 2, 0, 'flex', '{"type":"flex","altText":"【15大特典への道 1/6】今日のミッション: 1問アンケートに回答（30秒）","contents":{"type":"bubble","size":"mega","header":{"type":"box","layout":"vertical","backgroundColor":"#D94A3D","paddingAll":"12px","contents":[{"type":"text","text":"15大特典への道 1/6","color":"#FFFFFF","weight":"bold","size":"sm","wrap":true}]},"body":{"type":"box","layout":"vertical","spacing":"md","paddingAll":"16px","contents":[{"type":"text","text":"FurimAutoです🎁\n\n無料期間中に集められる15大特典、①②のロードマップは受け取りましたか？","size":"sm","color":"#555555","wrap":true},{"type":"box","layout":"vertical","backgroundColor":"#FFF6E5","cornerRadius":"8px","paddingAll":"12px","contents":[{"type":"text","text":"今日のミッション🎯\n▶ 1問アンケートに回答（30秒）","size":"sm","color":"#E8730C","wrap":true,"weight":"bold"}]},{"type":"text","text":"クリアでもらえる特典\n📘 ③ ロードマップ❸\n📘 ④ ロードマップ❹\n\n物販で稼ぐ道筋の\"続き\"です。\n今朝ご案内したリサーチ機能とセットでどうぞ。\n\n特典の受け取りは、リッチメニューの「限定特典GET」をタップ👇","size":"sm","color":"#555555","wrap":true,"margin":"md"}]},"footer":{"type":"box","layout":"vertical","spacing":"sm","contents":[{"type":"button","style":"primary","height":"sm","color":"#D94A3D","action":{"type":"message","label":"アンケート開始（30秒）","text":"【ボタン】アンケート開始"}}]}}}', 1, NULL, '13:00');

-- Day2朝 リサーチカルーセル＋15大特典
INSERT INTO scenario_steps (id, scenario_id, step_order, delay_minutes, message_type, message_content, offset_days, offset_minutes, delivery_time)
VALUES ('4748a328-4a81-489b-b693-3985ff75ad3e', '373c47a6-0197-419d-89ed-9e01dcc298c4', 3, 0, 'flex', '{"type":"flex","altText":"【何が売れるかは、\"事実\"で分かります】無料リサーチの2枚のカードをどうぞ","contents":{"type":"carousel","contents":[{"type":"bubble","size":"mega","header":{"type":"box","layout":"vertical","backgroundColor":"#2FA25B","paddingAll":"12px","contents":[{"type":"text","text":"無料ステップ 2/3｜何が売れるかを知る","color":"#FFFFFF","weight":"bold","size":"sm","wrap":true}]},"body":{"type":"box","layout":"vertical","spacing":"md","paddingAll":"16px","contents":[{"type":"text","text":"何が売れるかは、\"事実\"で分かります","size":"lg","color":"#333333","wrap":true,"weight":"bold"},{"type":"text","text":"勘で仕入れると、在庫が残ります。\n\n売れている人は「売れた事実」から逆算して仕入れています。\n\nFurimAutoの無料リサーチなら、その事実が、ぜんぶ見えます。","size":"sm","color":"#555555","wrap":true},{"type":"box","layout":"vertical","backgroundColor":"#F0FAF4","cornerRadius":"8px","paddingAll":"12px","contents":[{"type":"text","text":"横にスワイプして、2つのリサーチカードをご覧ください →","size":"sm","color":"#2FA25B","wrap":true,"weight":"bold"}]}]}},{"type":"bubble","size":"mega","header":{"type":"box","layout":"vertical","backgroundColor":"#2FA25B","paddingAll":"12px","contents":[{"type":"text","text":"無料リサーチ｜商品ページ","color":"#FFFFFF","weight":"bold","size":"sm","wrap":true}]},"hero":{"type":"image","url":"https://furimauto.com/howto/images/freeToolCard_overview.png","size":"full","aspectRatio":"1420:1536","aspectMode":"cover"},"body":{"type":"box","layout":"vertical","spacing":"md","paddingAll":"16px","contents":[{"type":"text","text":"🔍 商品ページでできるリサーチ","size":"lg","color":"#333333","wrap":true,"weight":"bold"},{"type":"box","layout":"vertical","backgroundColor":"#FFF1EC","cornerRadius":"8px","paddingAll":"12px","spacing":"xs","contents":[{"type":"text","text":"💰 出品者の\"期間別売上金額\"が見える","size":"md","color":"#D94A3D","wrap":true,"weight":"bold"},{"type":"text","text":"直近90日の販売実績を自動表示。期間別に何個・いくら売れたかが丸わかりです。","size":"sm","color":"#555555","wrap":true}]},{"type":"box","layout":"vertical","backgroundColor":"#FFF6E5","cornerRadius":"8px","paddingAll":"12px","spacing":"xs","contents":[{"type":"text","text":"📤 ワンクリックでコピー出品","size":"md","color":"#E8730C","wrap":true,"weight":"bold"},{"type":"text","text":"メルカリの商品を、そのまま他のフリマサイトへ。出品し直しの手間がなくなります。","size":"sm","color":"#555555","wrap":true}]},{"type":"text","text":"ほかにも、8サイト横断リサーチ・商品画像の一括保存がこのカードから使えます。","size":"xs","color":"#888888","wrap":true,"margin":"md"}]}},{"type":"bubble","size":"mega","header":{"type":"box","layout":"vertical","backgroundColor":"#2FA25B","paddingAll":"12px","contents":[{"type":"text","text":"無料リサーチ｜出品者ページ","color":"#FFFFFF","weight":"bold","size":"sm","wrap":true}]},"hero":{"type":"image","url":"https://furimauto.com/howto/images/shopResearch_panels.png","size":"full","aspectRatio":"2874:1630","aspectMode":"cover"},"body":{"type":"box","layout":"vertical","spacing":"md","paddingAll":"16px","contents":[{"type":"text","text":"🏪 出品者ページでできるリサーチ","size":"lg","color":"#333333","wrap":true,"weight":"bold"},{"type":"text","text":"参考にしたいアカウント、競合アカウントの\"戦略\"を丸裸にします。","size":"sm","color":"#555555","wrap":true},{"type":"box","layout":"vertical","backgroundColor":"#FFF1EC","cornerRadius":"8px","paddingAll":"12px","spacing":"xs","contents":[{"type":"text","text":"⚡ 数百ページを、数分で分析","size":"md","color":"#D94A3D","wrap":true,"weight":"bold"},{"type":"text","text":"出品傾向・価格帯を自動で集計。手作業では追い切れない量を一気に分析できます。","size":"sm","color":"#555555","wrap":true}]},{"type":"box","layout":"vertical","backgroundColor":"#FFF6E5","cornerRadius":"8px","paddingAll":"12px","spacing":"xs","contents":[{"type":"text","text":"⭐ 評価も、その場で確認","size":"md","color":"#E8730C","wrap":true,"weight":"bold"},{"type":"text","text":"購入者からの評価一覧をページ内に表示。\"信頼される売り方\"まで研究できます。","size":"sm","color":"#555555","wrap":true}]}]}}]}}', 2, NULL, '09:00');
INSERT INTO scenario_steps (id, scenario_id, step_order, delay_minutes, message_type, message_content, offset_days, offset_minutes, delivery_time)
VALUES ('fe672b05-f3d8-44e0-bb73-6aada771629c', '373c47a6-0197-419d-89ed-9e01dcc298c4', 4, 0, 'flex', '{"type":"flex","altText":"🎁 無料期間中に15大特典をGETしよう！","contents":{"type":"bubble","size":"mega","header":{"type":"box","layout":"vertical","backgroundColor":"#2FA25B","paddingAll":"12px","contents":[{"type":"text","text":"無料ステップ 2/3｜15大特典","color":"#FFFFFF","weight":"bold","size":"sm","wrap":true}]},"hero":{"type":"image","url":"https://furimauto.com/service/images/special_offer.png","size":"full","aspectRatio":"1:1","aspectMode":"cover"},"body":{"type":"box","layout":"vertical","spacing":"md","paddingAll":"16px","contents":[{"type":"text","text":"そして、リサーチと一緒に受け取ってほしいものがあります🎁\n\n無料期間中に段階的に解放される【15大特典】です。物販ロードマップから撮影マニュアルまで。まずは\"今すぐもらえる特典\"からどうぞ👇","size":"sm","color":"#333333","wrap":true},{"type":"separator","margin":"md"},{"type":"text","text":"📦 今すぐもらえる特典","size":"sm","color":"#333333","wrap":true,"weight":"bold","margin":"md"},{"type":"button","style":"link","height":"sm","action":{"type":"uri","label":"① ロードマップ❶（PDF）","uri":"https://storage.googleapis.com/furimauto_line/tokuten/%E7%89%B9%E5%85%B81%E3%83%AD%E3%83%BC%E3%83%88%E3%82%99%E3%83%9E%E3%83%83%E3%83%95%E3%82%9A%E2%9D%B6.pdf"}},{"type":"button","style":"link","height":"sm","action":{"type":"uri","label":"② ロードマップ❷（PDF）","uri":"https://storage.googleapis.com/furimauto_line/tokuten/%E7%89%B9%E5%85%B82%E3%83%AD%E3%83%BC%E3%83%88%E3%82%99%E3%83%9E%E3%83%83%E3%83%95%E3%82%9A%E2%9D%B7.pdf"}},{"type":"separator","margin":"md"},{"type":"text","text":"🔓 使うほどもらえる特典（リッチメニューから）","size":"sm","color":"#333333","wrap":true,"weight":"bold","margin":"md"},{"type":"text","text":"③④ ロードマップ❸❹\n⑤⑥ 撮影方法マニュアル 前編・後編\n⑦⑧ 外注化マニュアル 前編・後編\n⑨⑩ 外注募集テンプレ・業務委託契約書\n⑪ コメントセールの手法と効果の解説\n⑫⑬ 売れるブランドリスト・アカウント解説","size":"xs","color":"#444444","wrap":true},{"type":"text","text":"🎬 YouTube視聴＋キーワード入力でもらえる特典","size":"sm","color":"#333333","wrap":true,"weight":"bold","margin":"md"},{"type":"text","text":"⑭ 初月半額クーポン\n⑮ 無料試用期間1週間延長","size":"xs","color":"#444444","wrap":true},{"type":"text","text":"リッチメニューの「限定特典GET」をタップすると、あなたの利用状況に応じて次の特典が届きます！","size":"xs","color":"#888888","wrap":true,"margin":"md"}]}}}', 2, NULL, '09:00');

