VALUES ('f12a3a85-d10c-4de9-945e-e3f27b3794fb', '373c47a6-0197-419d-89ed-9e01dcc298c4', 5, 0, 'flex', '{"type":"flex","altText":"【15大特典への道 2/6】今日のミッション: キーコードを発行する（無料・30秒）","contents":{"type":"bubble","size":"mega","header":{"type":"box","layout":"vertical","backgroundColor":"#D94A3D","paddingAll":"12px","contents":[{"type":"text","text":"15大特典への道 2/6","color":"#FFFFFF","weight":"bold","size":"sm","wrap":true}]},"body":{"type":"box","layout":"vertical","spacing":"md","paddingAll":"16px","contents":[{"type":"text","text":"いい商品も、写真が悪いと売れません📷","size":"sm","color":"#555555","wrap":true},{"type":"box","layout":"vertical","backgroundColor":"#FFF6E5","cornerRadius":"8px","paddingAll":"12px","contents":[{"type":"text","text":"今日のミッション🎯\n▶ キーコードを発行する（無料・30秒）","size":"sm","color":"#E8730C","wrap":true,"weight":"bold"}]},{"type":"text","text":"クリアでもらえる特典\n📕 ⑤ 撮影方法マニュアル 前編\n📕 ⑥ 撮影方法マニュアル 後編\n\n\"売れる写真\"の撮り方を体系化した教材です。\n出品の質が、今日から変わります。\n\n発行は下のボタンから。特典はリッチメニューの「限定特典GET」から受け取れます👇","size":"sm","color":"#555555","wrap":true,"margin":"md"}]},"footer":{"type":"box","layout":"vertical","spacing":"sm","contents":[{"type":"button","style":"primary","height":"sm","color":"#F68A1D","action":{"type":"message","label":"キーコード発行","text":"【リッチメニュー】キーコード発行"}}]}}}', 2, NULL, '13:00');

-- Day3朝 コピー出品
INSERT INTO scenario_steps (id, scenario_id, step_order, delay_minutes, message_type, message_content, offset_days, offset_minutes, delivery_time)
VALUES ('1bbe61af-7f8d-4b85-8763-16f9a0853c09', '373c47a6-0197-419d-89ed-9e01dcc298c4', 6, 0, 'flex', '{"type":"flex","altText":"【他サイトへの出品、ワンクリックで終わります】無料のコピー出品をご存知ですか","contents":{"type":"bubble","size":"mega","header":{"type":"box","layout":"vertical","backgroundColor":"#2FA25B","paddingAll":"12px","contents":[{"type":"text","text":"無料ステップ 3/3｜コピー出品","color":"#FFFFFF","weight":"bold","size":"sm","wrap":true}]},"body":{"type":"box","layout":"vertical","spacing":"md","paddingAll":"16px","contents":[{"type":"text","text":"他サイトへの出品、ワンクリックで終わります","size":"lg","color":"#333333","wrap":true,"weight":"bold"},{"type":"text","text":"リサーチで「売れるもの」が見えたら、次は出品です。\n\nFurimAutoの無料機能でいちばん人気なのが【コピー出品】。\n\nメルカリの商品ページからワンクリックで、メルカリShops・ラクマ・ヤフオク・Yahoo!フリマへそのままコピー出品できます。","size":"sm","color":"#555555","wrap":true},{"type":"text","text":"▼ 商品ページに出るツールカード。「コピー出品」から1クリックです","size":"xs","color":"#2FA25B","wrap":true,"weight":"bold","margin":"md"},{"type":"image","url":"https://furimauto.com/howto/images/freeToolCard_overview.png","size":"full","aspectRatio":"1420:1536","aspectMode":"cover"},{"type":"text","text":"画像の一括保存・商品情報の追加表示・8サイト横断リサーチなどの無料機能も、このカードに揃っています。","size":"xs","color":"#888888","wrap":true,"margin":"md"},{"type":"separator","margin":"md"},{"type":"box","layout":"vertical","backgroundColor":"#FFF1EC","cornerRadius":"8px","paddingAll":"12px","contents":[{"type":"text","text":"ただ、正直にお伝えします。\nリサーチと出品が整っても、毎日の値下げ・コメント対応・取引メッセージは消えません。商品数が増えるほど、手が止まります。","size":"sm","color":"#D94A3D","wrap":true,"weight":"bold"}]},{"type":"text","text":"そこでFurimAutoの本体です。\nいまの無料期間中は、【自動化の全機能】もすべて使えます。\n\n発行は下のボタンをタップするだけ。\nクレジットカードの登録は不要、期間が終わっても勝手に課金されることはありません👇","size":"sm","color":"#555555","wrap":true,"margin":"md"}]},"footer":{"type":"box","layout":"vertical","spacing":"sm","contents":[{"type":"button","style":"primary","height":"sm","color":"#F68A1D","action":{"type":"message","label":"キーコード発行","text":"【リッチメニュー】キーコード発行"}}]}}}', 3, NULL, '09:00');

