VALUES ('9d2f51e6-91ef-4de1-b14f-1390064d426e', '373c47a6-0197-419d-89ed-9e01dcc298c4', 7, 0, 'flex', '{"type":"flex","altText":"【15大特典への道 3/6】今日のミッション: キーコードを拡張機能に入力して自動化を1つ実行","contents":{"type":"bubble","size":"mega","header":{"type":"box","layout":"vertical","backgroundColor":"#D94A3D","paddingAll":"12px","contents":[{"type":"text","text":"15大特典への道 3/6","color":"#FFFFFF","weight":"bold","size":"sm","wrap":true}]},"body":{"type":"box","layout":"vertical","spacing":"md","paddingAll":"16px","contents":[{"type":"text","text":"昨日発行したキーコード、もう使ってみましたか？","size":"sm","color":"#555555","wrap":true},{"type":"box","layout":"vertical","backgroundColor":"#FFF6E5","cornerRadius":"8px","paddingAll":"12px","contents":[{"type":"text","text":"今日のミッション🎯\n▶ 発行したキーコードを拡張機能に入力して\n　自動化を1つ実行する","size":"sm","color":"#E8730C","wrap":true,"weight":"bold"}]},{"type":"text","text":"クリアでもらえる特典\n📗 ⑦ 外注化マニュアル 前編\n📗 ⑧ 外注化マニュアル 後編\n\n自分の作業を\"人に任せる\"仕組み化の教科書。\n自動化と外注化で、稼働はさらに減らせます。\n\n受け取りはリッチメニューの「限定特典GET」をタップ👇","size":"sm","color":"#555555","wrap":true,"margin":"md"}]}}}', 3, NULL, '13:00');

-- Day4朝 FurimAutoの5段階
INSERT INTO scenario_steps (id, scenario_id, step_order, delay_minutes, message_type, message_content, offset_days, offset_minutes, delivery_time)
VALUES ('77fd252b-85fb-4f25-90af-b0bf93728a02', '373c47a6-0197-419d-89ed-9e01dcc298c4', 8, 0, 'flex', '{"type":"flex","altText":"【FurimAutoが、リサーチを無料で配る理由】少しだけ、私たちの話をさせてください","contents":{"type":"bubble","size":"mega","header":{"type":"box","layout":"vertical","backgroundColor":"#2FA25B","paddingAll":"12px","contents":[{"type":"text","text":"FurimAutoの5段階","color":"#FFFFFF","weight":"bold","size":"sm","wrap":true}]},"body":{"type":"box","layout":"vertical","spacing":"md","paddingAll":"16px","contents":[{"type":"text","text":"FurimAutoが、リサーチを無料で配る理由","size":"lg","color":"#333333","wrap":true,"weight":"bold"},{"type":"text","text":"少しだけ、私たちの話をさせてください。\n\nFurimAutoは、現役のフリマ物販プレイヤーが作っている自動化ツールです。\n\n先に、身も蓋もない事実からお伝えします。\n\nフリマ物販に適したジャンルは、すでに世の中に出きっています。\n\nそして、いま売上が立っているアカウントこそが\"答え合わせの済んだ成功例\"です。\n\nだから、自分に合ったジャンルのトッププレイヤーを丸ごと真似する。それだけの、シンプルな事業です。\n\nオリジナリティは、むしろ邪魔になります。","size":"sm","color":"#555555","wrap":true},{"type":"box","layout":"vertical","backgroundColor":"#F0FAF4","cornerRadius":"8px","paddingAll":"12px","contents":[{"type":"text","text":"私たちが「今のフリマサイトでの成功の順番」だと確信しているのが、この5段階です。重要度も、①から順になっています。","size":"sm","color":"#2FA25B","wrap":true,"weight":"bold"}]},{"type":"text","text":"① 何が売れるかを、事実で知る\n② 売れる商品を仕入れて、\n　いい写真・丁寧な情報を添えて出品する\n③ 毎日の作業を自動化して、売上を継続させる\n④ 販路を広げて、売上の上限を外す\n⑤ 増えた在庫を、事故なく回す","size":"sm","color":"#333333","wrap":true,"weight":"bold"},{"type":"text","text":"リサーチせずに仕入れた在庫は残ります。\n1つのサイトだけの運用には、天井が来ます。\n\nFurimAutoはこの5段階を、ぜんぶ1つの拡張機能に入れました。\n\nそして──\n入り口の①と②は、無料です。\n無料期間が終わっても、ずっと無料のままです。\n\nなぜそんなことをするのか。\n\nお金をお支払いいただいて活用してほしいのは、\n「商品が増えて、手が回らなくなった時」\nその時だけだからです。\n\nお客様のニーズは、百種百様です。\n商材・戦略・資金力・お使いのPCスペックまで、すべて異なります。\n\nそのニーズに応えられるように、FurimAutoは様々なサービス・機能を用意しています。\n\n\"人手が欲しくなった作業\"から、少しずつ任せてください。\n\nあなたが売れる。忙しくなる。\n「もう手作業には戻れない」と感じる。\nその時はじめて、次の段が目の前に現れる。\n\nFurimAutoは、そういう順番で使ってもらえるように作られています。\n\nさて、いまのあなたは、どの段にいますか？👇","size":"sm","color":"#555555","wrap":true},{"type":"image","url":"https://furimauto.com/line_images/roadmap_5steps.png","size":"full","aspectRatio":"1:1","aspectMode":"cover","margin":"md"}]}}}', 4, NULL, '09:00');

-- Day4昼 特典への道4/6＋チケット
INSERT INTO scenario_steps (id, scenario_id, step_order, delay_minutes, message_type, message_content, offset_days, offset_minutes, delivery_time)
VALUES ('ace00b49-2b71-41ad-b0fc-8ca49872b986', '373c47a6-0197-419d-89ed-9e01dcc298c4', 9, 0, 'flex', '{"type":"flex","altText":"【15大特典への道 4/6】今日のミッション: 無料チケット30枚を受け取ってコピー出品を試す","contents":{"type":"bubble","size":"mega","header":{"type":"box","layout":"vertical","backgroundColor":"#D94A3D","paddingAll":"12px","contents":[{"type":"text","text":"15大特典への道 4/6","color":"#FFFFFF","weight":"bold","size":"sm","wrap":true}]},"body":{"type":"box","layout":"vertical","spacing":"md","paddingAll":"16px","contents":[{"type":"text","text":"無料のコピー出品チケット30枚、もう受け取りましたか？🎫","size":"sm","color":"#555555","wrap":true},{"type":"box","layout":"vertical","backgroundColor":"#FFF6E5","cornerRadius":"8px","paddingAll":"12px","contents":[{"type":"text","text":"今日のミッション🎯\n▶ 無料チケット30枚を受け取って\n　コピー出品を試す","size":"sm","color":"#E8730C","wrap":true,"weight":"bold"}]},{"type":"text","text":"クリアでもらえる特典\n📄 ⑨ 外注募集テンプレート\n📄 ⑩ 外注先業務委託契約書テンプレ\n\n昨日のマニュアルを\"今日から実行\"できる実物のテンプレートです。\n\nチケットは下のカードから、特典はリッチメニューの「限定特典GET」から👇","size":"sm","color":"#555555","wrap":true,"margin":"md"}]}}}', 4, NULL, '13:00');
INSERT INTO scenario_steps (id, scenario_id, step_order, delay_minutes, message_type, message_content, offset_days, offset_minutes, delivery_time)
VALUES ('7eb371d7-86a8-4563-bcf1-60a30572f981', '373c47a6-0197-419d-89ed-9e01dcc298c4', 10, 0, 'flex', '{"type":"flex","altText":"コピー出品チケット30枚無料でプレゼント！","contents":{"type":"bubble","size":"mega","header":{"type":"box","layout":"vertical","backgroundColor":"#D94A3D","paddingAll":"12px","contents":[{"type":"text","text":"コピー出品チケット30枚 無料","color":"#FFFFFF","weight":"bold","size":"sm","wrap":true}]},"hero":{"type":"image","url":"https://storage.googleapis.com/furimauto_line/images/messageEvent/copy_function.png","size":"full","aspectRatio":"16:9","aspectMode":"cover"},"body":{"type":"box","layout":"vertical","spacing":"md","paddingAll":"16px","contents":[{"type":"text","text":"コピー出品チケット30枚無料でプレゼント！","size":"lg","color":"#333333","wrap":true,"weight":"bold"},{"type":"text","text":"🎉【30枚のコピー出品チケットを無料でプレゼント！】🎉\n\nメルカリShops・ラクマ・ヤフオク・Yahoo!フリマへのコピー出品が可能！\n\n商品をコピー出品完了したら1枚消費するチケット制度で、コピー出品だけならサブスクプランへの加入は不要🙅‍♀️\n\n💬下のボタンをタップした後、キーコードの入力ボタンを押すだけですぐにご利用いただけます！","size":"sm","color":"#555555","wrap":true}]},"footer":{"type":"box","layout":"vertical","spacing":"sm","contents":[{"type":"button","style":"primary","height":"sm","color":"#F68A1D","action":{"type":"message","label":"GETする","text":"【ボタン】コピー出品チケット30枚GET"}}]}}}', 4, NULL, '13:00');

-- Day5昼 特典への道5/6
INSERT INTO scenario_steps (id, scenario_id, step_order, delay_minutes, message_type, message_content, offset_days, offset_minutes, delivery_time)
VALUES ('152a7312-2f51-4ea8-958f-fb3cfebf3447', '373c47a6-0197-419d-89ed-9e01dcc298c4', 11, 0, 'flex', '{"type":"flex","altText":"【15大特典への道 5/6】今日のミッション: YouTube動画講座を見てキーワードを送る","contents":{"type":"bubble","size":"mega","header":{"type":"box","layout":"vertical","backgroundColor":"#D94A3D","paddingAll":"12px","contents":[{"type":"text","text":"15大特典への道 5/6","color":"#FFFFFF","weight":"bold","size":"sm","wrap":true}]},"body":{"type":"box","layout":"vertical","spacing":"md","paddingAll":"16px","contents":[{"type":"box","layout":"vertical","backgroundColor":"#FFF6E5","cornerRadius":"8px","paddingAll":"12px","contents":[{"type":"text","text":"今日のミッション🎯\n▶ YouTube動画講座を見て、\n　動画内のキーワードをこのLINEに送る","size":"sm","color":"#E8730C","wrap":true,"weight":"bold"}]},{"type":"text","text":"クリアでもらえる特典\n📙 ⑪ コメントセールの手法と効果の解説\n\n商品にいいねした人へ\"追いセールコメント\"を打つ手法を深掘りした資料です。値引き幅の考え方まで分かります。\n\n動画はリッチメニューの「Youtube動画講座」からどうぞ👇","size":"sm","color":"#555555","wrap":true,"margin":"md"},{"type":"image","url":"https://storage.googleapis.com/furimauto_line/images/messageEvent/youtube_coupon.png","size":"full","aspectRatio":"16:9","aspectMode":"cover","margin":"md"},{"type":"box","layout":"vertical","backgroundColor":"#FFF1EC","cornerRadius":"8px","paddingAll":"12px","contents":[{"type":"text","text":"【お得に使えるクーポンをGET!!】\n動画内のキーワードをLINEに送っていただいた方には、\n・友達登録から1週間以内 → 月額半額クーポン\n・それ以外 → 月額20%引きクーポン\nをそれぞれプレゼントいたします！","size":"sm","color":"#D94A3D","wrap":true,"weight":"bold"}]}]}}}', 5, NULL, '13:00');

-- Day6昼 特典への道6/6
INSERT INTO scenario_steps (id, scenario_id, step_order, delay_minutes, message_type, message_content, offset_days, offset_minutes, delivery_time)
VALUES ('3930148e-269e-48ca-a829-628bef7bea56', '373c47a6-0197-419d-89ed-9e01dcc298c4', 12, 0, 'flex', '{"type":"flex","altText":"【15大特典への道 6/6】最終日。いちばん大きい特典です","contents":{"type":"bubble","size":"mega","header":{"type":"box","layout":"vertical","backgroundColor":"#D94A3D","paddingAll":"12px","contents":[{"type":"text","text":"15大特典への道 6/6","color":"#FFFFFF","weight":"bold","size":"sm","wrap":true}]},"body":{"type":"box","layout":"vertical","spacing":"md","paddingAll":"16px","contents":[{"type":"text","text":"最終日。いちばん大きい特典です。","size":"sm","color":"#555555","wrap":true},{"type":"box","layout":"vertical","backgroundColor":"#FFF6E5","cornerRadius":"8px","paddingAll":"12px","contents":[{"type":"text","text":"今日のミッション🎯\n▶ 完全解説動画を見て、動画内で案内される\n　キーワードをこのLINEに送る","size":"sm","color":"#E8730C","wrap":true,"weight":"bold"}]},{"type":"text","text":"クリアでもらえる特典\n📒 ⑫ 売れるブランドリスト\n📒 ⑬ 売れるアカウント説明&プロフィール解説","size":"sm","color":"#555555","wrap":true,"margin":"md"},{"type":"box","layout":"vertical","backgroundColor":"#FFF1EC","cornerRadius":"8px","paddingAll":"12px","contents":[{"type":"text","text":"さらに──\n🎁 無料試用期間が1週間延長されます","size":"sm","color":"#D94A3D","wrap":true,"weight":"bold"}]},{"type":"text","text":"「まだ試し切れていない」という方も、これでもう1週間、じっくり使えます。\n\n動画はリッチメニューからどうぞ👇","size":"sm","color":"#555555","wrap":true,"margin":"md"}]}}}', 6, NULL, '13:00');

-- Day7朝 全自動化1分動画
INSERT INTO scenario_steps (id, scenario_id, step_order, delay_minutes, message_type, message_content, offset_days, offset_minutes, delivery_time)
VALUES ('81ee562e-6529-4dfa-97fa-f449ccca8acc', '373c47a6-0197-419d-89ed-9e01dcc298c4', 13, 0, 'flex', '{"type":"flex","altText":"おはようございます☀ 今日はまず、この1分動画だけ見てください","contents":{"type":"bubble","size":"mega","header":{"type":"box","layout":"vertical","backgroundColor":"#F68A1D","paddingAll":"12px","contents":[{"type":"text","text":"DAY 7｜1分で分かる全自動化","color":"#FFFFFF","weight":"bold","size":"sm","wrap":true}]},"hero":{"type":"image","url":"https://img.youtube.com/vi/uQjheVeAuww/maxresdefault.jpg","size":"full","aspectRatio":"16:9","aspectMode":"cover","action":{"type":"uri","uri":"https://www.youtube.com/watch?v=uQjheVeAuww"}},"body":{"type":"box","layout":"vertical","spacing":"md","paddingAll":"16px","contents":[{"type":"text","text":"おはようございます☀","size":"lg","color":"#333333","wrap":true,"weight":"bold"},{"type":"text","text":"FurimAutoです。\n\n今日はまず、この動画だけ見てください。\n\nFurimAutoが目指す「全自動化」──新規出品と梱包発送以外の毎日の作業をぜんぶ任せる、という世界が1分で分かります。","size":"sm","color":"#555555","wrap":true},{"type":"text","text":"長ったらしい説明はナシ！です🙅‍♀️\n使い方と他社ツールと比べた特徴を1分でまとめました!!","size":"xs","color":"#888888","wrap":true,"margin":"md"}]},"footer":{"type":"box","layout":"vertical","spacing":"sm","contents":[{"type":"button","style":"primary","height":"sm","color":"#FF0000","action":{"type":"uri","label":"YouTubeで見る","uri":"https://www.youtube.com/watch?v=uQjheVeAuww"}}]}}}', 7, NULL, '09:00');

-- Day8朝 フリマSEO
INSERT INTO scenario_steps (id, scenario_id, step_order, delay_minutes, message_type, message_content, offset_days, offset_minutes, delivery_time)
VALUES ('28b01035-9411-43d9-a0e0-6f02b80b2d22', '373c47a6-0197-419d-89ed-9e01dcc298c4', 14, 0, 'flex', '{"type":"flex","altText":"【値下げと再出品は、何のためにやるのか】フリマサイト内のSEO対策の話です","contents":{"type":"bubble","size":"mega","header":{"type":"box","layout":"vertical","backgroundColor":"#F68A1D","paddingAll":"12px","contents":[{"type":"text","text":"DAY 8｜今日はここ：出品一覧ページ","color":"#FFFFFF","weight":"bold","size":"sm","wrap":true}]},"hero":{"type":"image","url":"https://furimauto.com/line_images/pages3_day2.png","size":"full","aspectRatio":"1:1","aspectMode":"cover"},"body":{"type":"box","layout":"vertical","spacing":"md","paddingAll":"16px","contents":[{"type":"text","text":"値下げと再出品は、何のためにやるのか","size":"lg","color":"#333333","wrap":true,"weight":"bold"},{"type":"text","text":"先に言い切ります。\n値下げや再出品を\"するだけ\"で売れるわけではありません。\n\nでも、フリマサイトにははっきりした傾向があります。\n\n値下げ・再出品をした商品は検索結果の上位に戻り、閲覧数が増え、いいねが集まる。","size":"sm","color":"#555555","wrap":true},{"type":"box","layout":"vertical","backgroundColor":"#FFF1EC","cornerRadius":"8px","paddingAll":"12px","contents":[{"type":"text","text":"つまりこれは【フリマサイト内のSEO対策】です","size":"md","color":"#D94A3D","wrap":true,"weight":"bold"}]},{"type":"image","url":"https://furimauto.com/line_images/seo_cycle.png","size":"full","aspectRatio":"1:1","aspectMode":"cover","margin":"md"},{"type":"text","text":"問題は、それを毎日手作業で続けられるか、です。\n\nFurimAutoなら、出品一覧ページの作業──値下げ・再出品・コメント管理・底値設定──を日時指定でまとめて予約でき、継続的に自動化できます。\n\nたとえば毎日の値段変更の予約の合間に、再出品を「朝10品・夜10品」で予約するだけで、1日20商品×30日、1ヶ月で約600品をフレッシュな商品ページとして回せます。","size":"sm","color":"#555555","wrap":true,"margin":"md"},{"type":"box","layout":"vertical","backgroundColor":"#FFF6E5","cornerRadius":"8px","paddingAll":"12px","contents":[{"type":"text","text":"今日はまず、自動値下げか自動再出品をどちらか1つだけ予約してみてください😊","size":"sm","color":"#333333","wrap":true,"weight":"bold"}]}]}}}', 8, NULL, '09:00');

-- Day9朝 価格ギャップ
INSERT INTO scenario_steps (id, scenario_id, step_order, delay_minutes, message_type, message_content, offset_days, offset_minutes, delivery_time)
VALUES ('80cd8895-3d2e-449e-a889-e8dd889890f6', '373c47a6-0197-419d-89ed-9e01dcc298c4', 15, 0, 'flex', '{"type":"flex","altText":"【売る側は高く、買う側は安くのギャップがチャンス】自動いいね対応の話です","contents":{"type":"bubble","size":"mega","header":{"type":"box","layout":"vertical","backgroundColor":"#F68A1D","paddingAll":"12px","contents":[{"type":"text","text":"DAY 9｜今日はここ：お知らせページ","color":"#FFFFFF","weight":"bold","size":"sm","wrap":true}]},"hero":{"type":"image","url":"https://furimauto.com/line_images/pages3_day3.png","size":"full","aspectRatio":"1:1","aspectMode":"cover"},"body":{"type":"box","layout":"vertical","spacing":"md","paddingAll":"16px","contents":[{"type":"text","text":"売る側は高く、買う側は安くのギャップがチャンス","size":"lg","color":"#333333","wrap":true,"weight":"bold"},{"type":"text","text":"物販の売上は、突き詰めるとこの綱引きです。\n\n売る側は、できるだけ高く売りたい。\n買う側は、できるだけ安く買いたい。\n\nこの\"価格のギャップ\"をどれだけ上手に詰められるかが、フリマサイトで売上を伸ばすいちばん大事な施策です。\n\nそして、昨日お伝えしたSEOで閲覧といいねを集めた\"その先\"にあるのが【価格交渉】です。","size":"sm","color":"#555555","wrap":true},{"type":"image","url":"https://furimauto.com/line_images/price_gap.png","size":"full","aspectRatio":"1:1","aspectMode":"cover","margin":"md"},{"type":"text","text":"いいねを付けた人は、「気になっているけど、あと一歩」の人。\n\nその人に向けてセールコメントを投稿し、こちらから能動的に\"交渉の場\"へお客さんを連れてくる──それがFurimAutoの【自動いいね対応】です。\n\n商品にいいねが付いたら、その人に向けたセールコメントを自動で投稿。\n\n買い手は少し安く買えて、あなたの在庫は現金に変わる。","size":"sm","color":"#555555","wrap":true,"margin":"md"},{"type":"box","layout":"vertical","backgroundColor":"#FFF6E5","cornerRadius":"8px","paddingAll":"12px","contents":[{"type":"text","text":"ギャップが縮まる瞬間を、体験してみてください😊","size":"sm","color":"#333333","wrap":true,"weight":"bold"}]}]}}}', 9, NULL, '09:00');

-- Day10朝 取引メッセージの重荷
INSERT INTO scenario_steps (id, scenario_id, step_order, delay_minutes, message_type, message_content, offset_days, offset_minutes, delivery_time)
VALUES ('b152b145-b61a-4492-ab03-aa7cbcf3c494', '373c47a6-0197-419d-89ed-9e01dcc298c4', 16, 0, 'flex', '{"type":"flex","altText":"【売れるほど、忙しくなる問題】取引メッセージも自動化できます","contents":{"type":"bubble","size":"mega","header":{"type":"box","layout":"vertical","backgroundColor":"#F68A1D","paddingAll":"12px","contents":[{"type":"text","text":"DAY 10｜今日はここ：取引中ページ","color":"#FFFFFF","weight":"bold","size":"sm","wrap":true}]},"hero":{"type":"image","url":"https://furimauto.com/line_images/pages3_day4.png","size":"full","aspectRatio":"1:1","aspectMode":"cover"},"body":{"type":"box","layout":"vertical","spacing":"md","paddingAll":"16px","contents":[{"type":"text","text":"売れるほど、忙しくなる問題","size":"lg","color":"#333333","wrap":true,"weight":"bold"},{"type":"text","text":"ここまでの自動化（値段変更・セールコメント施策・再出品）がうまく回り始めると、閲覧が増え、いいねが増え、月間の取引数も増えやすくなります。\n\nすると、次に重くなるのが──\n【取引メッセージのやり取り】です。\n\n購入のお礼、発送のご連絡、受取確認。\n\nメッセージ1通の処理は、スマホでコピペしても1分〜1分半。1つの取引で3〜4通やり取りするので、取引1件あたり4〜5分かかる計算です。","size":"sm","color":"#555555","wrap":true},{"type":"image","url":"https://furimauto.com/line_images/msg_workload.png","size":"full","aspectRatio":"1:1","aspectMode":"cover","margin":"md"},{"type":"text","text":"取引が増えるほど、これが毎日積み上がっていきます。\n\nFurimAutoは、ここも自動化できます。\n\n取引メッセージを自動で送信。対応の早い出品者として購入者からの印象・評価にもつながります。","size":"sm","color":"#555555","wrap":true,"margin":"md"},{"type":"box","layout":"vertical","backgroundColor":"#FFF6E5","cornerRadius":"8px","paddingAll":"12px","contents":[{"type":"text","text":"売れるほど、ラクになる。\n全自動化の完成が、近づいてきました。","size":"sm","color":"#333333","wrap":true,"weight":"bold"}]}]}}}', 10, NULL, '09:00');

-- Day11朝 販路拡大
INSERT INTO scenario_steps (id, scenario_id, step_order, delay_minutes, message_type, message_content, offset_days, offset_minutes, delivery_time)
VALUES ('c8833859-f2c3-4cf2-b355-e2fa15d39317', '373c47a6-0197-419d-89ed-9e01dcc298c4', 17, 0, 'flex', '{"type":"flex","altText":"【1つのサイトで回ったら、次のステージへ】販路拡大はコピー出品で","contents":{"type":"bubble","size":"mega","header":{"type":"box","layout":"vertical","backgroundColor":"#F68A1D","paddingAll":"12px","contents":[{"type":"text","text":"DAY 11｜販路拡大","color":"#FFFFFF","weight":"bold","size":"sm","wrap":true}]},"body":{"type":"box","layout":"vertical","spacing":"md","paddingAll":"16px","contents":[{"type":"text","text":"1つのサイトで回ったら、次のステージへ","size":"lg","color":"#333333","wrap":true,"weight":"bold"},{"type":"text","text":"メルカリの運用が自動で回るようになったら、次にやるべきは【販路拡大】です。\n\n同じ商品でも、サイトが違えばお客さんも違う。出す場所を増やすだけで、売れるチャンスは単純に増えます。\n\n「でも、他のサイトに出品し直すのは面倒…」\n\nFurimAutoなら、メルカリの商品データをもとに他のフリマサイトへ一気にコピー出品できます。","size":"sm","color":"#555555","wrap":true},{"type":"image","url":"https://furimauto.com/line_images/copy_compare.png","size":"full","aspectRatio":"1:1","aspectMode":"cover","margin":"md"},{"type":"text","text":"・無料でも、ワンクリックの手動コピーが使えます\n・有料なら、1品あたり10〜15円のチケット制で全自動の連続出品","size":"sm","color":"#555555","wrap":true,"margin":"md"},{"type":"box","layout":"vertical","backgroundColor":"#FFF6E5","cornerRadius":"8px","paddingAll":"12px","contents":[{"type":"text","text":"販路拡大は、思っているよりずっと簡単です。\nまずは1品だけ、試しにコピーしてみてください😊","size":"sm","color":"#333333","wrap":true,"weight":"bold"}]}]}}}', 11, NULL, '09:00');

-- Day12朝 在庫管理
INSERT INTO scenario_steps (id, scenario_id, step_order, delay_minutes, message_type, message_content, offset_days, offset_minutes, delivery_time)
VALUES ('820b376c-1f31-42a6-8a8e-e097a0cf1162', '373c47a6-0197-419d-89ed-9e01dcc298c4', 18, 0, 'flex', '{"type":"flex","altText":"【最後の壁は、在庫管理】自動併売在庫管理で売り違いは構造的に起きません","contents":{"type":"bubble","size":"mega","header":{"type":"box","layout":"vertical","backgroundColor":"#F68A1D","paddingAll":"12px","contents":[{"type":"text","text":"DAY 12｜最後の壁は在庫管理","color":"#FFFFFF","weight":"bold","size":"sm","wrap":true}]},"body":{"type":"box","layout":"vertical","spacing":"md","paddingAll":"16px","contents":[{"type":"text","text":"最後の壁は、在庫管理","size":"lg","color":"#333333","wrap":true,"weight":"bold"},{"type":"text","text":"販路を広げると、最後にぶつかる壁があります。\n\n「メルカリで売れたのに、ラクマにも出したままだった…」\n\n複数サイトでの在庫管理は地味で、そしてミスが命取りです。\n\nFurimAutoの【自動併売在庫管理】は、どこかのサイトで売れたら、他のサイトの同じ商品を自動で取り下げます。","size":"sm","color":"#555555","wrap":true},{"type":"image","url":"https://furimauto.com/line_images/inventory_sync.png","size":"full","aspectRatio":"1:1","aspectMode":"cover","margin":"md"},{"type":"text","text":"売り違いの恐怖から解放されて、あなたがやるのは仕入れて、出品して、発送するだけ。\n\nリサーチ → 出品 → 自動化 → 販路拡大 → 在庫管理。\n\nこの2週間でご案内した階段をのぼり切ると、\"片手間なのに、ちゃんと伸びる物販\"が完成します。","size":"sm","color":"#555555","wrap":true,"margin":"md"},{"type":"box","layout":"vertical","backgroundColor":"#FFF6E5","cornerRadius":"8px","paddingAll":"12px","contents":[{"type":"text","text":"その形、このまま続けませんか？\n今夜、継続してご利用になりたい方へ向けたご案内をお送りします😊","size":"sm","color":"#333333","wrap":true,"weight":"bold"}]}]}}}', 12, NULL, '09:00');

-- 3) friend_add: ウェルカム文言（2週間）＋start_scenarioを新IDへ
UPDATE automation_actions SET
  params = '{"messages":[{"messageType":"flex","altText":"友だち追加ありがとうございます🎉 2週間の無料試用期間がスタートしました！","content":"{\"type\":\"bubble\",\"size\":\"mega\",\"header\":{\"type\":\"box\",\"layout\":\"vertical\",\"backgroundColor\":\"#2FA25B\",\"paddingAll\":\"12px\",\"contents\":[{\"type\":\"text\",\"text\":\"FurimAuto｜ようこそ\",\"color\":\"#FFFFFF\",\"weight\":\"bold\",\"size\":\"sm\",\"wrap\":true}]},\"body\":{\"type\":\"box\",\"layout\":\"vertical\",\"spacing\":\"md\",\"paddingAll\":\"16px\",\"contents\":[{\"type\":\"text\",\"text\":\"友だち追加ありがとうございます🎉\",\"size\":\"lg\",\"color\":\"#333333\",\"wrap\":true,\"weight\":\"bold\"},{\"type\":\"text\",\"text\":\"FurimAuto（フリマート）です。\\n\\nたった今からFurimAuto内の全ての機能を解放した【2週間の無料試用期間】がスタートしました！\\n\\nまずはChrome拡張機能の導入から。\\n下の動画のとおりに進めるだけ、1分で終わります👇\",\"size\":\"sm\",\"color\":\"#555555\",\"wrap\":true}]},\"footer\":{\"type\":\"box\",\"layout\":\"vertical\",\"spacing\":\"sm\",\"contents\":[{\"type\":\"button\",\"style\":\"primary\",\"height\":\"sm\",\"color\":\"#2FA25B\",\"action\":{\"type\":\"uri\",\"label\":\"導入ページを開く\",\"uri\":\"https://furimauto.com/install\"}}]}}"},{"messageType":"video","content":"{\"originalContentUrl\":\"https://storage.googleapis.com/furimauto_line/video/install.mp4\",\"previewImageUrl\":\"https://storage.googleapis.com/furimauto_line/video/install_thumnail.png\",\"trackingId\":\"setup\"}"}]}',
  label = 'ウェルカム2通送信（Flex版・14日）',
  updated_at = datetime('now', '+9 hours')
WHERE automation_id = (SELECT id FROM automations WHERE event_type = 'friend_add' LIMIT 1)
  AND step_order = 7;
UPDATE automation_actions SET
  params = '{"scenarioId":"373c47a6-0197-419d-89ed-9e01dcc298c4"}',
  updated_at = datetime('now', '+9 hours')
WHERE automation_id = (SELECT id FROM automations WHERE event_type = 'friend_add' LIMIT 1)
  AND action_type = 'start_scenario';

-- 4) closing_daily: 4通差し替え（残1日文面の「この2週間で」反映）
DELETE FROM automation_actions WHERE automation_id = (SELECT id FROM automations WHERE event_type = 'closing_daily' LIMIT 1) AND action_type = 'send_messages';
INSERT INTO automation_actions (id, automation_id, step_order, action_type, params, condition_json, is_active, label, created_at, updated_at)
SELECT 'b75ff34f-479b-47d9-b871-4117fa6a6a0d', id, 0, 'send_messages', '{"messages":[{"messageType":"flex","altText":"【現在地の確認です】無料期間は残り5日になりました","content":"{\"type\":\"bubble\",\"size\":\"mega\",\"header\":{\"type\":\"box\",\"layout\":\"vertical\",\"backgroundColor\":\"#222222\",\"paddingAll\":\"12px\",\"contents\":[{\"type\":\"text\",\"text\":\"無料期間 残り5日\",\"color\":\"#FFFFFF\",\"weight\":\"bold\",\"size\":\"sm\",\"wrap\":true}]},\"body\":{\"type\":\"box\",\"layout\":\"vertical\",\"spacing\":\"md\",\"paddingAll\":\"16px\",\"contents\":[{\"type\":\"text\",\"text\":\"現在地の確認です\",\"size\":\"lg\",\"color\":\"#333333\",\"wrap\":true,\"weight\":\"bold\"},{\"type\":\"text\",\"text\":\"FurimAutoです。\\n無料期間は残り5日になりました。\\n\\nいま、自分がどこまで来たか確認してみてください。\",\"size\":\"sm\",\"color\":\"#555555\",\"wrap\":true},{\"type\":\"box\",\"layout\":\"vertical\",\"backgroundColor\":\"#FFF6E5\",\"cornerRadius\":\"8px\",\"paddingAll\":\"12px\",\"contents\":[{\"type\":\"text\",\"text\":\"✅ リサーチで売れるものが分かる（無料）\\n✅ 出品まわりの補助機能（無料）\\n⬜ 値下げ・再出品などの自動化（無料期間中に体験できます）\\n⬜ コピー出品での販路拡大\\n⬜ 併売の在庫管理\",\"size\":\"sm\",\"color\":\"#333333\",\"wrap\":true,\"weight\":\"bold\"}]},{\"type\":\"text\",\"text\":\"正直にお伝えすると、基本のリサーチと出品まわりの機能は期間が終わっても無料のまま使えます。\\n\\n有料になるのは「自動化」から先です。\\n\\n残り5日。まだ試していない自動化があれば、今のうちに動かしてみてください。\\n\\n「使い方がよく分からない…」という方は、【Youtube動画講座】が近道です🎬\\n入門から上級まで、段階的に理解できます👇\",\"size\":\"sm\",\"color\":\"#555555\",\"wrap\":true,\"margin\":\"md\"},{\"type\":\"text\",\"text\":\"\\\"手放せるかどうか\\\"は、体験した人にしか分かりません。\",\"size\":\"sm\",\"color\":\"#333333\",\"wrap\":true,\"weight\":\"bold\",\"margin\":\"md\"}]},\"footer\":{\"type\":\"box\",\"layout\":\"vertical\",\"spacing\":\"sm\",\"contents\":[{\"type\":\"button\",\"style\":\"primary\",\"height\":\"sm\",\"color\":\"#FF0000\",\"action\":{\"type\":\"uri\",\"label\":\"Youtube動画講座を見る\",\"uri\":\"https://youtube.com/playlist?list=PLUhATsy78sfvUHMVmeQpKMyxATlHOCEeF&si=4ZT_HFKCIGcuHibG\"}}]}}"}]}', '{"remaining_days_gte":5,"remaining_days_lte":5}', 1, '残5日: 現在地の確認（Flex版）', datetime('now', '+9 hours'), datetime('now', '+9 hours')
FROM automations WHERE event_type = 'closing_daily' LIMIT 1;
INSERT INTO automation_actions (id, automation_id, step_order, action_type, params, condition_json, is_active, label, created_at, updated_at)
SELECT 'd5da8732-fcd2-4534-ad3d-e051fc40ced0', id, 1, 'send_messages', '{"messages":[{"messageType":"flex","altText":"【時給換算、してみませんか】いちばんお得に始める方法をご案内します","content":"{\"type\":\"bubble\",\"size\":\"mega\",\"header\":{\"type\":\"box\",\"layout\":\"vertical\",\"backgroundColor\":\"#222222\",\"paddingAll\":\"12px\",\"contents\":[{\"type\":\"text\",\"text\":\"無料期間 残り3日\",\"color\":\"#FFFFFF\",\"weight\":\"bold\",\"size\":\"sm\",\"wrap\":true}]},\"body\":{\"type\":\"box\",\"layout\":\"vertical\",\"spacing\":\"md\",\"paddingAll\":\"16px\",\"contents\":[{\"type\":\"text\",\"text\":\"時給換算、してみませんか\",\"size\":\"lg\",\"color\":\"#333333\",\"wrap\":true,\"weight\":\"bold\"},{\"type\":\"text\",\"text\":\"毎日の値下げ・コメント・取引メッセージ。\\n仮に1日30分なら、1ヶ月で約15時間です。\\n\\n時給1,000円で換算すると、月15,000円ぶん。\\n\\nFurimAutoの自動化は最安480円/月〜から始められます。\",\"size\":\"sm\",\"color\":\"#555555\",\"wrap\":true},{\"type\":\"box\",\"layout\":\"vertical\",\"backgroundColor\":\"#FFF1EC\",\"cornerRadius\":\"8px\",\"paddingAll\":\"12px\",\"contents\":[{\"type\":\"text\",\"text\":\"そして、いちばんお得に始める方法がこちら🎁\\nリッチメニューの【Youtube動画講座】を見て、動画内で案内されるキーワードをこのLINEに送ってください。\",\"size\":\"sm\",\"color\":\"#D94A3D\",\"wrap\":true,\"weight\":\"bold\"}]},{\"type\":\"image\",\"url\":\"https://storage.googleapis.com/furimauto_line/images/messageEvent/youtube_coupon.png\",\"size\":\"full\",\"aspectRatio\":\"16:9\",\"aspectMode\":\"cover\",\"margin\":\"md\"},{\"type\":\"text\",\"text\":\"【お得に使えるクーポンをGET!!】\\n\\n動画内のキーワードをLINEに送っていただいた方には、\\n\\n・友達登録から1週間以内 → 月額半額クーポン\\n・それ以外 → 月額20%引きクーポン\\n\\nをそれぞれプレゼントいたします！\\n\\nFurimAutoの\\\"全自動化\\\"を理解できるうえに、初回決済で使える割引クーポンが届きます👇\",\"size\":\"sm\",\"color\":\"#555555\",\"wrap\":true,\"margin\":\"md\"}]},\"footer\":{\"type\":\"box\",\"layout\":\"vertical\",\"spacing\":\"sm\",\"contents\":[{\"type\":\"button\",\"style\":\"primary\",\"height\":\"sm\",\"color\":\"#D94A3D\",\"action\":{\"type\":\"uri\",\"label\":\"プラン診断をはじめる\",\"uri\":\"https://liff.line.me/1660804123-ZfTZnrBV\"}}]}}"}]}', '{"remaining_days_gte":3,"remaining_days_lte":3}', 1, '残3日: 時給換算＋クーポン導線（Flex版）', datetime('now', '+9 hours'), datetime('now', '+9 hours')
FROM automations WHERE event_type = 'closing_daily' LIMIT 1;
INSERT INTO automation_actions (id, automation_id, step_order, action_type, params, condition_json, is_active, label, created_at, updated_at)
SELECT '7b225d48-ef04-4529-83cb-e0961cfea743', id, 2, 'send_messages', '{"messages":[{"messageType":"flex","altText":"【登録は、思っているより簡単です】最短3分で自動化がそのまま続きます","content":"{\"type\":\"bubble\",\"size\":\"mega\",\"header\":{\"type\":\"box\",\"layout\":\"vertical\",\"backgroundColor\":\"#222222\",\"paddingAll\":\"12px\",\"contents\":[{\"type\":\"text\",\"text\":\"無料期間 残り2日\",\"color\":\"#FFFFFF\",\"weight\":\"bold\",\"size\":\"sm\",\"wrap\":true}]},\"body\":{\"type\":\"box\",\"layout\":\"vertical\",\"spacing\":\"md\",\"paddingAll\":\"16px\",\"contents\":[{\"type\":\"text\",\"text\":\"登録は、思っているより簡単です\",\"size\":\"lg\",\"color\":\"#333333\",\"wrap\":true,\"weight\":\"bold\"},{\"type\":\"text\",\"text\":\"「手続きが面倒そう」と思っていませんか？\\n\\nFurimAutoの登録に、説明会や面談はありません。\",\"size\":\"sm\",\"color\":\"#555555\",\"wrap\":true},{\"type\":\"box\",\"layout\":\"vertical\",\"backgroundColor\":\"#FFF6E5\",\"cornerRadius\":\"8px\",\"paddingAll\":\"12px\",\"contents\":[{\"type\":\"text\",\"text\":\"① プラン診断で自分に合うプランを確認（1分）\\n② そのまま画面から申し込み\\n③ クレジットカード決済で完了\",\"size\":\"sm\",\"color\":\"#333333\",\"wrap\":true,\"weight\":\"bold\"}]},{\"type\":\"text\",\"text\":\"これだけです。最短3分で、いま体験中の自動化がそのまま続きます。\\n\\n無料期間は残り2日。\\nプラン選びに迷ったら、このLINEにそのまま返信してください😊\",\"size\":\"sm\",\"color\":\"#555555\",\"wrap\":true,\"margin\":\"md\"}]},\"footer\":{\"type\":\"box\",\"layout\":\"vertical\",\"spacing\":\"sm\",\"contents\":[{\"type\":\"button\",\"style\":\"primary\",\"height\":\"sm\",\"color\":\"#D94A3D\",\"action\":{\"type\":\"uri\",\"label\":\"プラン診断をはじめる\",\"uri\":\"https://liff.line.me/1660804123-ZfTZnrBV\"}}]}}"}]}', '{"remaining_days_gte":2,"remaining_days_lte":2}', 1, '残2日: 登録は簡単（Flex版）', datetime('now', '+9 hours'), datetime('now', '+9 hours')
FROM automations WHERE event_type = 'closing_daily' LIMIT 1;
INSERT INTO automation_actions (id, automation_id, step_order, action_type, params, condition_json, is_active, label, created_at, updated_at)
SELECT '4e3a628c-6791-45cf-b5e3-c99a4489e123', id, 3, 'send_messages', '{"messages":[{"messageType":"flex","altText":"【本日で無料期間が終了します】最後にもう一度だけ、背中を押させてください","content":"{\"type\":\"bubble\",\"size\":\"mega\",\"header\":{\"type\":\"box\",\"layout\":\"vertical\",\"backgroundColor\":\"#222222\",\"paddingAll\":\"12px\",\"contents\":[{\"type\":\"text\",\"text\":\"本日で無料期間終了\",\"color\":\"#FFFFFF\",\"weight\":\"bold\",\"size\":\"sm\",\"wrap\":true}]},\"body\":{\"type\":\"box\",\"layout\":\"vertical\",\"spacing\":\"md\",\"paddingAll\":\"16px\",\"contents\":[{\"type\":\"text\",\"text\":\"本日で無料期間が終了します\",\"size\":\"lg\",\"color\":\"#333333\",\"wrap\":true,\"weight\":\"bold\"},{\"type\":\"text\",\"text\":\"FurimAutoです。\\n\\n明日以降、キーコードが無効になり、設定済みの自動化（値下げ・再出品・いいね対応など）は停止します。\",\"size\":\"sm\",\"color\":\"#555555\",\"wrap\":true},{\"type\":\"box\",\"layout\":\"vertical\",\"backgroundColor\":\"#F0FAF4\",\"cornerRadius\":\"8px\",\"paddingAll\":\"12px\",\"contents\":[{\"type\":\"text\",\"text\":\"ただ、ご安心ください。\\nリサーチなどの無料機能はこれからも、ずっと使えます。\",\"size\":\"sm\",\"color\":\"#2FA25B\",\"wrap\":true,\"weight\":\"bold\"}]},{\"type\":\"text\",\"text\":\"そのうえで──\\n\\nこの2週間で「もう手作業には戻りたくない」と感じたなら、それが答えだと思います。\\n\\n登録はプラン診断から最短3分。\\n割引クーポンがまだの方は、完全解説動画の中で案内されるキーワードを送るだけで受け取れます。\\n\\n最後にもう一度だけ、背中を押させてください👇\",\"size\":\"sm\",\"color\":\"#555555\",\"wrap\":true,\"margin\":\"md\"}]},\"footer\":{\"type\":\"box\",\"layout\":\"vertical\",\"spacing\":\"sm\",\"contents\":[{\"type\":\"button\",\"style\":\"primary\",\"height\":\"sm\",\"color\":\"#FF0000\",\"action\":{\"type\":\"uri\",\"label\":\"完全解説動画を見る\",\"uri\":\"https://youtu.be/jhaCPxgE_Sk\"}},{\"type\":\"button\",\"style\":\"primary\",\"height\":\"sm\",\"color\":\"#D94A3D\",\"action\":{\"type\":\"uri\",\"label\":\"プラン診断をはじめる\",\"uri\":\"https://liff.line.me/1660804123-ZfTZnrBV\"}}]}}"}]}', '{"remaining_days_gte":1,"remaining_days_lte":1}', 1, '残1日: 本日で無料期間終了（Flex版）', datetime('now', '+9 hours'), datetime('now', '+9 hours')
FROM automations WHERE event_type = 'closing_daily' LIMIT 1;
